    | H : peframe _ _ _ _ _ _ _ _ _ |- _ => clear H
    | H : pecells _ _ _ _ _ _ |- _ => clear H
    | H : petot _ _ _ |- _ => clear H
    | H : pesize _ _ _ |- _ => clear H
    | H : pinb _ _ _ _ |- _ => clear H
    | H : pshb _ _ _ |- _ => clear H
    | H : ptsh _ _ |- _ => clear H
    | H : mem_inv _ _ |- _ => clear H
    | H : pectx _ _ _ _ _ _ _ _ _ |- _ => clear H
    | H : pecore _ _ _ _ _ |- _ => clear H
    | E : ?f ?rk = _ |- _ => lazymatch type of rk with rv => tryif is_areg f then fail else clear E end
    end.
  Ltac chase_all := repeat match goal with E : ?f ?rk = _ |- _ => is_areg f; lazymatch type of rk with rv => progress (rewrite E in * ) end end.
  Ltac leaf_atom := first [ eassumption | reflexivity | eqt
